rows=[]
for line in section('1.18').splitlines():
    if not re.match(r'\| \d+ \|',line):continue
    cells=[c.strip() for c in line.strip('|').split('|')];n=int(cells[0]);name=cells[1];purpose,fields,states,actions,layout=detail[n]
    sn,f1,f2=mapping.get(n,(None,None,None));s=next((s for s in site if s['name']==sn),None)
    ft=lambda id:next((f for f in fig if f['id']==id),None)
    typ='overlay' if n in [9,11,13,15,16,17,18,27] else 'screen'
    row={'feature':'A1','name':name,'type':typ,'order':n,'prd':str(prd.relative_to(ROOT)).replace('\\','/'),'section':f'§1.18 row {n}; §1.7; §2.4','purpose':purpose,'required_fields':fields,'states':states,'actions':actions,'layout_improvements':layout,'entry':cells[3],'destinations':cells[4],'frame1':ft(f1),'frame2':ft(f2),'site_reference':sn,'exact_site_copy':s['text'] if s else '', 'site_elements':s['elements'] if s else [],'source_screen_paths':[],'selected_prd_ux_text':section('2.4'),'edge_case_source':section('1.10'),'conflicts':['G-01','G-02','G-03'] if n in range(2,9) else (['G-04'] if n==12 else []),'execution_status':'Documentation prepared; approval and any copy gaps resolved before Figma execution'}
    if sn:row['source_screen_paths']=[str(p.relative_to(ROOT)).replace('\\','/') for p in (ROOT/'Screens/Mobile App/Onboarding').glob(sn+'*.png')]
    rows.append(row)
(OUT/'Research/onboarding-enriched.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
manifest=[]
for p in sorted((ROOT/'PRD_Documents').rglob('*')):
    if not p.is_file():continue
    rel=str(p.relative_to(ROOT)).replace('\\','/'); b=p.read_bytes()
    scope='Mobile requirement source' if re.search(r'Feature_[ABCF]\d+_',p.name) else 'Supporting brand/list source' if 'Icon-Banner' in rel or 'Total Feature' in p.name else 'Excluded web/admin scope'
    manifest.append({'path':rel,'scope':scope,'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'review':'Mobile source audited in research; remaining source read for scope classification only' if scope.startswith('Mobile') else 'Catalogued; not used to create web/admin screens'})
(OUT/'Evidence/source-manifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
print({'onboarding_records':len(rows),'source_files':len(manifest)})
